from typing import List

def check(args: List, got: List[int], expected: List[int]) -> bool:
    nums, k = args
    from collections import Counter
    count = Counter(nums)

    if len(got) != k:
        return False

    seen = set()
    for x in got:
        if x in seen or x not in count:
            return False
        seen.add(x)

    min_freq_in_got = min(count[x] for x in got)
    for x, freq in count.items():
        if x not in seen and freq > min_freq_in_got:
            return False

    return True

