class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        count = collections.Counter(nums)
        freq = [[] for _ in range(len(nums) + 1)]
        for num, cnt in count.items():
            freq[cnt].append(num)

        res = []
        for i in range(len(freq) - 1, 0, -1):
            for num in freq[i]:
                res.append(num)
                if len(res) == k:
                    return res
        return res

data.reference_solution:
def topKFrequent(nums: List[int], k: int) -> List[int]:
    unique_elements = []
    for x in nums:
        if x not in unique_elements:
            unique_elements.append(x)

    element_counts = []
    for x in unique_elements:
        count = 0
        for y in nums:
            if y == x:
                count += 1
        element_counts.append((count, x))

    element_counts.sort(key=lambda item: item[0], reverse=True)

    result = []
    for i in range(k):
        result.append(element_counts[i][1])
    return result

